// OCI volume IDs cannot be reused; a verified TERMINATED observation stays true.
type volumeTermination struct {
	VolumeID           string    `json:"volume_id"`
	Region             Region    `json:"region"`
	Owner              string    `json:"owner"`
	CompartmentID      string    `json:"compartment_id"`
	AvailabilityDomain string    `json:"availability_domain"`
	ObservedAt         time.Time `json:"observed_at"`
}

func (journal *KVJournal) volumeTerminated(ctx context.Context, config RegionConfig, volumeID string) (bool, error) {
	entry, err := journal.read(ctx, ownershipKey("volume-termination", volumeID))
	if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, jetstream.ErrKeyDeleted) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	proof := entry.VolumeTermination
	if entry.Kind != "volume-termination" || proof.VolumeID != volumeID || proof.Region != config.Region ||
		proof.Owner != config.Owner || proof.CompartmentID != config.CompartmentID ||
		proof.AvailabilityDomain != config.AvailabilityDomain || proof.ObservedAt.IsZero() ||
		proof.ObservedAt.Location() != time.UTC {
		return false, errors.New("OCI volume termination proof has a different or corrupt scope")
	}
	return true, nil
}

func (journal *KVJournal) RecordVolumeTermination(ctx context.Context, config RegionConfig, volumeID string) error {
	if volumeID == "" || config.Owner == "" || config.Region == "" || config.CompartmentID == "" || config.AvailabilityDomain == "" {
		return errors.New("OCI volume termination proof requires complete scope")
	}
	proof := volumeTermination{VolumeID: volumeID, Region: config.Region, Owner: config.Owner,
		CompartmentID: config.CompartmentID, AvailabilityDomain: config.AvailabilityDomain,
		ObservedAt: time.Now().UTC()}
	data, err := json.Marshal(journalEntry{SchemaVersion: journalSchema, Kind: "volume-termination", VolumeTermination: proof})
	if err != nil {
		return err
	}
	if _, err := journal.kv.Create(ctx, ownershipKey("volume-termination", volumeID), data); err == nil {
		return nil
	} else if !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("persist OCI volume termination proof: %w", err)
	}
	terminated, err := journal.volumeTerminated(ctx, config, volumeID)
	if err != nil {
		return err
	}
	if !terminated {
		return errors.New("OCI volume termination proof disappeared before readback")
	}
	return nil
}

type failTerminationCreateKV struct{ jetstream.KeyValue }

func (kv failTerminationCreateKV) Create(context.Context, string, []byte, ...jetstream.KVCreateOpt) (uint64, error) {
	return 0, errors.New("termination proof write unavailable")
}

// OpenJournal creates or opens the regional replicated OCI operation bucket.
// Replicas must match the regional controller quorum configuration.
func OpenJournal(ctx context.Context, js jetstream.JetStream, replicas int) (*KVJournal, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("OCI journal requires JetStream and one to five replicas")
	}
	kv, err := js.CreateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket:       journalBucket,
		Description:  "Durable OCI mutation intent and resource ownership",
		MaxValueSize: journalMaxValueSize,
		History:      5,
		Storage:      jetstream.FileStorage,
		Replicas:     replicas,
		Compression:  true,
	})
	if err != nil {
		if !errors.Is(err, jetstream.ErrBucketExists) {
			return nil, fmt.Errorf("create OCI journal bucket: %w", err)
		}
		kv, err = js.KeyValue(ctx, journalBucket)
		if err != nil {
			return nil, fmt.Errorf("open existing OCI journal bucket: %w", err)
		}
		status, statusErr := kv.Status(ctx)
		if statusErr != nil {
			return nil, fmt.Errorf("inspect OCI journal bucket: %w", statusErr)
		}
		config := status.Config()
		if config.Replicas != replicas || config.Storage != jetstream.FileStorage || config.TTL != 0 || config.History < 2 || config.MaxValueSize > journalMaxValueSize {
			return nil, errors.New("existing OCI journal bucket has incompatible durability limits")
		}
	}
	return NewKVJournal(kv)
}

// NewKVJournal wraps a caller-provisioned regional JetStream KV bucket. The
// caller is responsible for using a durable, quorum-replicated bucket.
func NewKVJournal(kv jetstream.KeyValue) (*KVJournal, error) {
	if kv == nil {
		return nil, errors.New("OCI journal KV bucket is required")
	}
	return &KVJournal{kv: kv}, nil
}

func (journal *KVJournal) read(ctx context.Context, key string) (journalEntry, error) {
	entry, err := journal.kv.Get(ctx, key)
	if err != nil {
		return journalEntry{}, err
	}
	return decodeJournalEntry(entry.Value())
}

func decodeJournalEntry(data []byte) (journalEntry, error) {
	var record journalEntry
	if err := json.Unmarshal(data, &record, json.RejectUnknownMembers(true)); err != nil {
		return journalEntry{}, fmt.Errorf("decode OCI journal record: %w", err)
	}
	if record.SchemaVersion != journalSchema {
		return journalEntry{}, errors.New("OCI journal record has unsupported schema version")
	}
	return record, nil

func ownershipKey(kind, id string) string {
	return entityid.Derive("oci-ownership", kind, id)
}

func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

func testJournalBucket(t *testing.T) jetstream.KeyValue {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 20*time.Second)
	defer cancel()
	runtime, err := startAuthenticatedJournal(ctx, authenticatedJournalConfig(t, "oci-journal-test"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = runtime.Close() })
	journal, err := OpenJournal(ctx, runtime.JetStream(), 1)
	if err != nil {
		t.Fatal(err)
	}
	return journal.kv
}

func authenticatedJournalConfig(t *testing.T, instance string) natscell.Config {
	t.Helper()
	const cell = "lab"
	root := t.TempDir()
	write := func(name string, wire []byte) string {
		t.Helper()
		path := filepath.Join(root, name)
		if err := os.WriteFile(path, wire, 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	key := func(kind nkeys.PrefixByte) (nkeys.KeyPair, string) {
		t.Helper()
		pair, err := nkeys.CreatePair(kind)
		if err != nil {
			t.Fatal(err)
		}
		t.Cleanup(pair.Wipe)
		public, err := pair.PublicKey()
		if err != nil {
			t.Fatal(err)
		}
		return pair, public
	}
	operator, operatorID := key(nkeys.PrefixByteOperator)
	system, systemID := key(nkeys.PrefixByteAccount)
	account, accountID := key(nkeys.PrefixByteAccount)
	claimFile := func(name string, claim jwt.Claims, signer nkeys.KeyPair) string {
		t.Helper()
		wire, err := claim.Encode(signer)
		if err != nil {
			t.Fatal(err)
		}
		return write(name, []byte(wire))
	}
	credentials := func(name string, user, signer nkeys.KeyPair, claim *jwt.UserClaims) string {
		t.Helper()
		wire, err := claim.Encode(signer)
		if err != nil {
			t.Fatal(err)
		}
		seed, err := user.Seed()
		if err != nil {
			t.Fatal(err)
		}
		defer clear(seed)
		creds, err := jwt.FormatUserConfig(wire, seed)
		if err != nil {
			t.Fatal(err)
		}
		defer clear(creds)
		return write(name, creds)
	}
	operatorClaim := jwt.NewOperatorClaims(operatorID)
	operatorClaim.SystemAccount = systemID
	accountClaim := jwt.NewAccountClaims(accountID)
	accountClaim.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: 64 << 20, DiskStorage: 256 << 20, Streams: 10, Consumer: 10}
	systemUser, systemUserID := key(nkeys.PrefixByteUser)
	systemClaim := jwt.NewUserClaims(systemUserID)
	systemClaim.IssuerAccount = systemID
	systemClaim.Pub.Allow = jwt.StringList{"$SYS.REQ.ACCOUNT." + accountID + ".CLAIMS.UPDATE"}
	systemClaim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(cell, systemUserID) + ".>"}
	controller, controllerID := key(nkeys.PrefixByteUser)
	controllerClaim := jwt.NewUserClaims(controllerID)
	controllerClaim.IssuerAccount = accountID
	controllerClaim.Pub.Allow = natscell.ControllerPublishes(cell)
	controllerClaim.Pub.Allow.Add("$JS.ACK.>")
	controllerClaim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(cell, controllerID) + ".>"}
	controllerClaim.Sub.Allow.Add(natscell.ControllerSubscriptions(cell)...)
	controllerClaim.Sub.Allow.Add(protocol.Broker(cell, "ticket", ">"), protocol.Broker(cell, "fence", instance))
	controllerClaim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}

	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now()
	ca := &x509.Certificate{SerialNumber: big.NewInt(1), Subject: pkix.Name{CommonName: "OCI journal test CA"},
		NotBefore: now.Add(-time.Hour), NotAfter: now.Add(time.Hour), IsCA: true, BasicConstraintsValid: true,
		KeyUsage: x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature}
	caDER, err := x509.CreateCertificate(rand.Reader, ca, ca, &caKey.PublicKey, caKey)
	if err != nil {
		t.Fatal(err)
	}
	peerKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	peer := &x509.Certificate{SerialNumber: big.NewInt(2), Subject: pkix.Name{CommonName: "OCI journal test peer"},
		NotBefore: now.Add(-time.Hour), NotAfter: now.Add(time.Hour), IPAddresses: []net.IP{net.ParseIP("127.0.0.1")},
		KeyUsage: x509.KeyUsageDigitalSignature, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth}}
	peerDER, err := x509.CreateCertificate(rand.Reader, peer, ca, &peerKey.PublicKey, caKey)
	if err != nil {
		t.Fatal(err)
	}
	keyDER, err := x509.MarshalECPrivateKey(peerKey)
	if err != nil {
		t.Fatal(err)
	}
	tlsFiles := natscell.TLSFiles{
		CAFile:   write("ca.pem", pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: caDER})),
		CertFile: write("peer.pem", pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: peerDER})),
		KeyFile:  write("peer-key.pem", pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER})),
	}
	ticketPublic, _, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	port := listener.Addr().(*net.TCPAddr).Port
	if err := listener.Close(); err != nil {
		t.Fatal(err)
	}
	cfg := natscell.Config{Cell: cell, Instance: instance, Replicas: 1, TLS: tlsFiles,
		CredentialsFile: credentials("controller.creds", controller, account, controllerClaim),
		Embedded: &natscell.Embedded{Host: "127.0.0.1", Port: port, StoreDir: filepath.Join(root, "jetstream"),
			TLS: tlsFiles, RouteTLS: tlsFiles, OperatorJWTFile: claimFile("operator.jwt", operatorClaim, operator),
			SystemJWTFile:         claimFile("system.jwt", jwt.NewAccountClaims(systemID), operator),
			CellJWTFile:           claimFile("cell.jwt", accountClaim, operator),
			SystemCredentialsFile: credentials("system.creds", systemUser, system, systemClaim),
			TicketPublicKeyFile:   write("ticket.pub", []byte(base64.StdEncoding.EncodeToString(ticketPublic))), BrokerIDs: []string{instance}}}
	if err := natscell.ValidateProductionCredentials(cfg); err != nil {
		t.Fatal(err)
	}
	return cfg
}

// Journal traffic crosses the production JWT/mutual-TLS bridge, including after disk restart.
type authenticatedJournalRuntime struct {
	*natscell.Runtime
	broker *natscell.Runtime
}

func (r *authenticatedJournalRuntime) Close() error {
	return errors.Join(r.Runtime.Close(), r.broker.Close())
}

func startAuthenticatedJournal(ctx context.Context, cfg natscell.Config) (_ *authenticatedJournalRuntime, err error) {
	broker, err := natscell.Start(ctx, cfg)
	if err != nil {
		return nil, err
	}
	defer func() {
		if err != nil {
			_ = broker.Close()
		}
	}()
	claim := broker.InitialCellJWT()
	if err = broker.ApplyCellClaim(ctx, 1, claim); err != nil {
		return nil, err
	}
	if err = broker.Bridge().OpenUntil(1, claim, time.Now().Add(5*time.Minute)); err != nil {
		return nil, err
	}
	cfg.URL, cfg.Embedded = broker.URL(), nil
	client, err := natscell.Start(ctx, cfg)
	if err != nil {
		return nil, err
	}
	return &authenticatedJournalRuntime{Runtime: client, broker: broker}, nil
}

func (r *Runtime) InitialCellJWT() string {
	if r == nil || r.resolver == nil {
		return ""
	}
	raw, _ := r.resolver.Fetch(r.resolver.cell)
	return raw
}

// ApplyCellClaim fences the external listener before installing a durable
// account replacement. A routed CLAIMS.UPDATE reply is never accepted as local
// proof; Accountz must report the exact raw JWT on this embedded server.
func (r *Runtime) ApplyCellClaim(ctx context.Context, sequence uint64, raw string) error {
	if r == nil || r.server == nil || r.resolver == nil || r.systemConn == nil ||
		sequence == 0 || raw == "" {
		return errors.New("production cell claim application is unavailable")
	}
	r.claimMu.Lock()
	defer r.claimMu.Unlock()
	if sequence < r.appliedSequence {
		return errors.New("cell claim sequence is stale")
	}
	if r.bridge != nil {
		r.bridge.FenceClaim(sequence)
	}
	if claim, err := jwt.DecodeAccountClaims(raw); err != nil || !r.SignedByPinnedOperator(claim) {
		return errors.New("cell claim is not signed by the pinned operator")
	}
	// Store runs the contract and issued-at checks; only then is the claim
	// installed, locally and directly. The server ignores CLAIMS.UPDATE
	// requests (see accountResolver.IsTrackingUpdate), so no routed or
	// client-sent claim can skip these checks.
	if err := r.resolver.Store(r.resolver.cell, raw); err != nil {
		return err
	}
	account, err := r.server.LookupAccount(r.resolver.cell)
	if err != nil {
		return err
	}
	current, err := r.server.Accountz(&server.AccountzOptions{Account: r.resolver.cell})
	if err != nil {
		return err
	}
	if current.Account == nil {
		return errors.New("cell account is not loaded")
	}
	if current.Account.Jwt != raw {
		if err := r.server.UpdateAccountClaimJWT(account, raw); err != nil {
			return fmt.Errorf("install cell account claim: %w", err)
		}
		current, err = r.server.Accountz(&server.AccountzOptions{Account: r.resolver.cell})
		if err != nil || current.Account == nil || current.Account.Jwt != raw {
			return errors.New("cell JWT update lacks local exact readback")
		}
	}
	r.appliedSequence = sequence
	return nil

func (r *Runtime) URL() string {
	if r.bridge != nil {
		return "nats://" + r.bridge.Addr().String()
	}
	if r.server != nil {
		return r.server.ClientURL()
	}
	return r.conn.ConnectedUrl()
}

func (r *Runtime) Close() error {
	if r == nil {
		return nil
	}
	r.once.Do(func() {
		if r.bridge != nil {
			r.bridge.Close()
		}
		if r.systemConn != nil {
			r.systemConn.Close()
		}
		if r.conn != nil {
			drainConnection(r.conn, closeDrainTimeout)
		}
		if r.server != nil {
			r.stopServer()
		}
	})
	return nil
}

// embeddedReadyTimeout bounds embedded server startup. JetStream cluster
// bootstrap on a loaded single-OCPU host can take well over ten seconds.
const embeddedReadyTimeout = time.Minute

// serverReady waits until the embedded server accepts connections, the
// caller's context ends, or embeddedReadyTimeout passes.
func serverReady(ctx context.Context, embedded *server.Server) bool {
	deadline := time.Now().Add(embeddedReadyTimeout)
	for ctx.Err() == nil && time.Now().Before(deadline) {
		if embedded.ReadyForConnections(time.Second) {
			return true
		}
	}
	return false
}

// Start starts the embedded server when requested and establishes an authenticated
// client connection. Multi-node callers must call WaitForCluster before mutations.
func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}

connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
defer cancel()
connected := make(chan struct{})
var connectErr, forwardErr error
go func() {
	connectURL := cfg.URL
	if cfg.Embedded == nil {
		if len(cfg.OperatorForward) != 0 {
			var selected string
			selected, _, forwardErr = operatorForwarding(cfg)
			if forwardErr != nil {
				close(connected)
				return
			}
			connectURL = selected
		}
		connectURL = bridgeClientURLs(connectURL)
	}
	r.conn, connectErr = nats.Connect(connectURL, options...)
	close(connected)
}()
select {
case <-connectCtx.Done():
	// nats.Connect has a bounded timeout of its own; wait for the goroutine
	// before cleaning up to avoid a late client after server shutdown.
	<-connected
	if forwardErr != nil {
		return nil, forwardErr
	}
	return nil, unavailable{connectCtx.Err()}
case <-connected:
}
if forwardErr != nil {
	return nil, forwardErr
}
if connectErr != nil {
	err := fmt.Errorf("connect regional NATS: %w", connectErr)
	if errors.Is(connectErr, nats.ErrAuthorization) {
		// The brokers answered and refused these credentials.
		return nil, err
	}
	return nil, unavailable{err}
}
if cfg.Embedded != nil {
	systemCfg := cfg
	systemCfg.NKeySeedFile = ""
	systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
	systemOptions, optionErr := clientOptions(systemCfg)
	if optionErr != nil {
		return nil, fmt.Errorf("system account client: %w", optionErr)
	}
	systemOptions = append(systemOptions, nats.InProcessServer(r.server))
	r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
	if err != nil {
		return nil, fmt.Errorf("connect internal system account: %w", err)
	}
	r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
	if err != nil {
		return nil, err
	}
	if !identityRekey {
		r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
			r.brokerTLS.ServerConfig(), r.resolver.cell)
		if err != nil {
			return nil, err
		}
	}

r.js, err = jetstream.New(r.conn)
if err != nil {
	return nil, fmt.Errorf("open regional JetStream: %w", err)
}
// A new R3 cell cannot elect a JetStream metadata leader until its peers
// have also started. The app calls WaitForCluster before any mutations.
if cfg.Replicas == 1 && cfg.ClientRole != "host" {
	infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
	defer infoCancel()
	if _, err := r.js.AccountInfo(infoCtx); err != nil {
		return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
	}
}
return r, nil

func (cfg Config) validate() error {
	if len(cfg.OperatorForward) != 0 {
		if _, _, err := operatorForwarding(cfg); err != nil {
			return err
		}
	}
	if !cellName.MatchString(cfg.Cell) || !cellName.MatchString(cfg.Instance) {
		return errors.New("cell and instance must be lowercase NATS tokens")
	}
	// Every protocol subject builder refuses the reserved scope as a cell
	// and returns "", which would surface far from here as empty grants.
	if cfg.Cell == protocol.GlobalScope {
		return errors.New("cell name is reserved for the global scope")
	}
	if cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 {
		return errors.New("regional replicas must be 1, 3, or 5")
	}
	if cfg.ClientRole != "" && cfg.ClientRole != "controller" && cfg.ClientRole != "operator" && cfg.ClientRole != "host" {
		return errors.New("invalid regional NATS client role")
	}
	if cfg.Embedded == nil && cfg.URL == "" {
		return errors.New("regional NATS URL or embedded server is required")
	}
	if cfg.NKeySeedFile != "" && cfg.CredentialsFile != "" {
		return errors.New("choose one regional NKey seed or JWT credentials file")
	}
	if !cfg.TLS.complete() || cfg.CredentialsFile == "" || cfg.NKeySeedFile != "" {
		return errors.New("regional NATS requires client TLS and JWT credentials")
	}
	if cfg.Embedded != nil && (!cfg.Embedded.TLS.complete() || !cfg.Embedded.RouteTLS.complete() ||
		cfg.Embedded.OperatorJWTFile == "" || cfg.Embedded.SystemJWTFile == "" ||
		cfg.Embedded.CellJWTFile == "" || cfg.Embedded.SystemCredentialsFile == "" ||
		cfg.Embedded.TicketPublicKeyFile == "" || len(cfg.Embedded.BrokerIDs) != cfg.Replicas || len(cfg.Embedded.Users) != 0) {
		return errors.New("production embedded NATS requires operator/system/cell JWTs, system credentials, and client/route TLS")
	}
	if cfg.Embedded != nil {
		e := cfg.Embedded
		if e.InterRegion != nil && e.Link != nil {
			return errors.New("a region links to peers by interregion or by link, not both")
		}
		if err := e.InterRegion.validate(cfg); err != nil {
			return err
		}
		if e.Link != nil {
			if err := e.Link.validate(cfg); err != nil {
				return err
			}
		}
		seen := make(map[string]struct{}, len(e.BrokerIDs))
		for _, id := range e.BrokerIDs {
			if !cellName.MatchString(id) {
				return errors.New("production broker ID is invalid")
			}
			if _, exists := seen[id]; exists {
				return errors.New("production broker IDs must be unique")
			}
			seen[id] = struct{}{}
		}
		if _, own := seen[cfg.Instance]; !own {
			return errors.New("production broker ID list excludes this instance")
		}
		if e.StoreDir == "" || e.Host == "" || e.Port == 0 {
			return errors.New("embedded NATS requires store_dir, host, and port")
		}
		if e.StoreMaxBytes < 0 {
			return errors.New("embedded NATS store_max_bytes must be positive when set")
		}
		if cfg.Replicas > 1 && (e.RouteHost == "" || e.RoutePort == 0 || len(e.Routes) == 0) {
			return errors.New("clustered NATS requires route_host, route_port and at least one seed route")
		}
		if cfg.Replicas > 1 && (e.RouteUser == "" || e.RoutePasswordFile == "") {
			return errors.New("production NATS routes require a route user and password file")
		}
	}
	return nil

func serverOptionsForStart(cfg Config, identityRekey bool) (*server.Options, error) {
	e := cfg.Embedded
	if err := os.MkdirAll(e.StoreDir, 0o700); err != nil {
		return nil, fmt.Errorf("create regional JetStream store: %w", err)
	}
	name := ServerName(cfg.Cell, cfg.Instance)
	if err := pinStoreIdentity(e.StoreDir, name, cfg.Cell+"-"+cfg.Instance); err != nil {
		return nil, err
	}
	options := &server.Options{
		ServerName:        name,
		Host:              e.Host,
		Port:              e.Port,
		JetStream:         true,
		JetStreamMaxStore: e.StoreLimitBytes(),
		StoreDir:          e.StoreDir,
		// JetStream clustering uses the system account to coordinate metadata.
		SystemAccount: "$SYS",
		Accounts:      []*server.Account{server.NewAccount("$SYS")},
		Cluster: server.ClusterOpts{
			Name: cfg.Cell,
			Host: e.RouteHost,
			Port: e.RoutePort,
		},
		LameDuckDuration:    lameDuckDuration,
		LameDuckGracePeriod: lameDuckGracePeriod,
		// NATS logs every failed reconnect to a lost route, gateway or leaf
		// at ERR by default: about one a second per pooled route while a peer
		// reboots. Report the first and then one a minute (TS-661).
		ReconnectErrorReports: reconnectErrorReports,
	}
	operator, systemJWT, cellJWT, systemID, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return nil, err
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, systemID); err != nil {
		return nil, err
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return nil, errors.New("controller credentials do not belong to the regional cell account")
	}
	resolver := newAccountResolver(systemID, systemJWT, cellID, cellJWT)
	options.TrustedOperators = []*jwt.OperatorClaims{operator}
	options.SystemAccount = systemID
	options.Accounts = nil
	options.AccountResolver = resolver
	options.JetStreamDomain = cfg.Cell
	options.DontListen = true
	options.Cluster.NoAdvertise = true
	if e.InterRegion != nil {
		if err := interRegionServerOptions(cfg, options, resolver, operator); err != nil {
			return nil, err
		}
	}
	if e.Link != nil {
		if err := linkServerOptions(cfg, options, resolver); err != nil {
			return nil, err
		}
	}

func clientOptions(cfg Config) ([]nats.Option, error) {
	connectTimeout := 12 * time.Second
	if cfg.ClientRole == "host" {
		connectTimeout = 3 * time.Second
	}
	options := []nats.Option{nats.Name("terrascale-" + cfg.Cell + "-" + cfg.Instance), nats.Timeout(connectTimeout),
		nats.ErrorHandler(ErrorHandler)}
	// Renewal applies to every authentication mode: an NKey-seed client has
	// no JWT to reload but must still present a renewed certificate.
	var materials *clientMaterialSource
	if cfg.ReloadClientMaterial != nil {
		materials = newClientMaterialSource(cfg, "")
	}
	if cfg.CredentialsFile != "" {
		data, err := readPrivateFile(cfg.CredentialsFile, 64<<10)
		if err != nil {
			return nil, fmt.Errorf("regional JWT credentials: %w", err)
		}
		pair, err := nkeys.ParseDecoratedUserNKey(data)
		clear(data)
		if err != nil {
			return nil, fmt.Errorf("regional JWT credentials: %w", err)
		}
		public, err := pair.PublicKey()
		pair.Wipe()
		if err != nil {
			return nil, err
		}
		options = append(options, nats.CustomInboxPrefix(inboxPrefix(cfg.Cell, public)))
		source := materials
		if source == nil {
			source = newClientMaterialSource(cfg, public)
		}
		source.user = public
		// The JWT and its signature come from one resolved file per handshake.
		var handshake ClientMaterial
		options = append(options, nats.UserJWT(func() (string, error) {
			handshake = source.current()
			data, err := readPrivateFile(handshake.CredentialsFile, 64<<10)
			if err != nil {
				return "", err
			}
			defer clear(data)
			return nkeys.ParseDecoratedJWT(data)
		}, func(nonce []byte) ([]byte, error) {
			path := handshake.CredentialsFile
			if path == "" {
				path = cfg.CredentialsFile
			}
			return signNKeyFile(path, nonce)
		}))
	}

	if cfg.TLS.complete() && cfg.Embedded == nil {
		tlsConfig, err := loadTLS(cfg.TLS, false)
		if err != nil {
			return nil, err
		}
		dialer := &tlsFirstDialer{config: tlsConfig, timeout: connectTimeout}
		if materials != nil {
			dialer.reload = materials.tlsConfig
		}
		if len(cfg.OperatorForward) != 0 {
			_, destinations, err := operatorForwarding(cfg)
			if err != nil {
				return nil, err
			}
			dialer.forward = destinations
			options = append(options, nats.IgnoreDiscoveredServers())
		}
		options = append(options, nats.SetCustomDialer(dialer))
	}
	return options, nil
}

func inboxPrefix(cell, publicKey string) string {
	return protocol.InboxPrefix(cell, publicKey)

func loadTLS(files TLSFiles, serverSide bool) (*tls.Config, error) {
	key, err := readPrivateFile(files.KeyFile, 64<<10)
	if err != nil {
		return nil, fmt.Errorf("NATS TLS private key: %w", err)
	}
	clear(key)
	certificate, err := tls.LoadX509KeyPair(files.CertFile, files.KeyFile)
	if err != nil {
		return nil, fmt.Errorf("load NATS certificate: %w", err)
	}
	ca, err := os.ReadFile(files.CAFile)
	if err != nil {
		return nil, fmt.Errorf("load NATS CA: %w", err)
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(ca) {
		return nil, errors.New("NATS CA file has no certificates")
	}
	config := &tls.Config{MinVersion: tls.VersionTLS13, Certificates: []tls.Certificate{certificate}, RootCAs: roots}
	if serverSide {
		config.ClientCAs = roots
		config.ClientAuth = tls.RequireAndVerifyClientCert
	}
	return config, nil
}

func signNKeyFile(path string, nonce []byte) ([]byte, error) {
	data, err := readPrivateFile(path, 64<<10)
	if err != nil {
		return nil, err
	}
	defer clear(data)
	pair, err := nkeys.ParseDecoratedUserNKey(data)
	if err != nil {
		return nil, err
	}
	defer pair.Wipe()
	return pair.Sign(nonce)

func readPrivateFile(path string, limit int64) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 {
		return nil, errors.New("secret must be a regular file readable only by its owner")
	}
	if stat, ok := info.Sys().(*syscall.Stat_t); ok && stat.Uid != uint32(os.Getuid()) {
		return nil, errors.New("secret must be owned by this process user")
	}
	if info.Size() > limit {
		return nil, errors.New("secret file is too large")
	}
	data, err := io.ReadAll(io.LimitReader(file, limit+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > limit {
		clear(data)
		return nil, errors.New("secret file is too large")
	}

func startBridge(s *server.Server, address string, tlsConfig *tls.Config, account string) (*Bridge, error) {
	if s == nil || tlsConfig == nil || account == "" {
		return nil, errors.New("production broker bridge is incomplete")
	}
	listener, err := tls.Listen("tcp", address, tlsConfig)
	if err != nil {
		return nil, fmt.Errorf("listen for regional broker clients: %w", err)
	}
	b := &Bridge{server: s, listener: listener, account: account, pairs: make(map[*bridgePair]struct{}), listeners: make(map[net.Listener]struct{})}
	go b.accept(listener)
	return b, nil
}

func (b *Bridge) OpenUntil(sequence uint64, rawJWT string, deadline time.Time) error {
	if b == nil || sequence == 0 || rawJWT == "" || !time.Now().Before(deadline) {
		return errors.New("broker bridge ticket is invalid or expired")
	}
	if _, err := b.server.LookupAccount(b.account); err != nil {
		return fmt.Errorf("load broker account: %w", err)
	}
	accountz, err := b.server.Accountz(&server.AccountzOptions{Account: b.account})
	if err != nil || accountz.Account == nil || accountz.Account.Jwt != rawJWT {
		return errors.New("broker account JWT was not applied locally")
	}
	b.mu.Lock()
	if b.closed || sequence < b.floor {
		b.mu.Unlock()
		return errors.New("broker bridge is closed or claim sequence is stale")
	}
	var pairs map[*bridgePair]struct{}
	if b.open && (b.sequence != sequence || b.jwt != rawJWT) {
		pairs = b.fenceLocked()
	}
	b.sequence, b.jwt, b.deadline, b.open = sequence, rawJWT, deadline, true
	if b.timer != nil {
		b.timer.Stop()
	}
	b.timer = time.AfterFunc(time.Until(deadline), func() {
		b.mu.Lock()
		var expired map[*bridgePair]struct{}
		if b.open && b.sequence == sequence && b.deadline.Equal(deadline) {
			expired = b.fenceLocked()
		}
		b.mu.Unlock()
		closeBridgeExternal(expired)
	})
	b.mu.Unlock()
	closeBridgeExternal(pairs)
	return nil
}

func (b *Bridge) Close() {
	if b == nil {
		return
	}
	b.mu.Lock()
	if b.closed {
		b.mu.Unlock()
		return
	}
	b.closed = true
	pairs := b.fenceLocked()
	listeners := b.listeners
	b.listeners = make(map[net.Listener]struct{})
	b.mu.Unlock()
	_ = b.listener.Close()
	for listener := range listeners {
		_ = listener.Close()
	}
	closeBridgeExternal(pairs)
}

func (b *Bridge) accept(listener net.Listener) {
	defer func() {
		b.mu.Lock()
		delete(b.listeners, listener)
		b.mu.Unlock()
	}()
	for {
		external, err := listener.Accept()
		if err != nil {
			return
		}
		b.mu.Lock()
		allowed := b.open && time.Now().Before(b.deadline) && !b.closed
		b.mu.Unlock()
		if !allowed {
			_ = external.Close()
			continue
		}
		go b.serve(external, listener)
	}
}

func (b *Bridge) serve(external net.Conn, listener net.Listener) {
	defer external.Close()
	if err := external.SetDeadline(time.Now().Add(5 * time.Second)); err != nil {
		return
	}
	if err := external.(*tls.Conn).Handshake(); err != nil {
		return
	}
	if err := external.SetDeadline(time.Time{}); err != nil {
		return
	}
	internal, err := b.server.InProcessConnForAccount(b.account)
	if err != nil {
		return
	}
	pair := &bridgePair{external: external, internal: internal, listener: listener}
	b.mu.Lock()
	_, additional := b.listeners[listener]
	if b.closed || listener != b.listener && !additional || !b.open || !time.Now().Before(b.deadline) {
		b.mu.Unlock()
		pair.close()
		return
	}
	b.pairs[pair] = struct{}{}
	b.mu.Unlock()
	done := make(chan struct{}, 2)
	go func() { _, _ = io.Copy(internal, external); done <- struct{}{} }()
	go func() { _, _ = io.Copy(external, internal); done <- struct{}{} }()
	<-done
	pair.close()
	<-done
	b.mu.Lock()
	delete(b.pairs, pair)
	b.mu.Unlock()
}

func (d *tlsFirstDialer) Dial(network, address string) (net.Conn, error) {
	destination, config := address, d.config
	if d.reload != nil {
		if current, err := d.reload(); err == nil {
			config = current
		}
	}
	if len(d.forward) != 0 {
		if network != "tcp" {
			return nil, errors.New("operator forward requires TCP")
		}
		mapped, ok := d.forward[address]
		if !ok {
			return nil, fmt.Errorf("NATS controller %q has no operator forward", address)
		}
		host, _, err := net.SplitHostPort(address)
		if err != nil {
			return nil, err
		}
		destination = mapped
		config = config.Clone()
		config.ServerName = host
	}
	conn, err := tls.DialWithDialer(&net.Dialer{Timeout: d.timeout}, network, destination, config)
	if err != nil {
		return nil, err
	}
	return conn, nil
}

func (*tlsFirstDialer) SkipTLSHandshake() bool { return true }

// nats.go treats tls:// as an instruction to wrap TLS after INFO even with a
// custom dialer. Keep every configured endpoint but prevent that second wrap.
func bridgeClientURLs(raw string) string {
	parts := strings.Split(raw, ",")
	for index, part := range parts {
		trimmed := strings.TrimSpace(part)
		if rest, ok := strings.CutPrefix(trimmed, "tls://"); ok {
			parts[index] = "nats://" + rest
		} else {
			parts[index] = trimmed
		}
	}
	return strings.Join(parts, ",")

func ValidateProductionCredentials(cfg Config) error {
	if cfg.Embedded == nil || cfg.ClientRole != "" && cfg.ClientRole != "controller" {
		return errors.New("controller credential preflight requires a production embedded broker")
	}
	if err := cfg.validate(); err != nil {
		return err
	}
	e := cfg.Embedded
	operator, systemRaw, cellRaw, _, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return err
	}
	system, err := jwt.DecodeAccountClaims(systemRaw)
	if err != nil {
		return fmt.Errorf("decode system account JWT: %w", err)
	}
	cell, err := jwt.DecodeAccountClaims(cellRaw)
	if err != nil {
		return fmt.Errorf("decode cell account JWT: %w", err)
	}
	for label, claim := range map[string]jwt.Claims{"operator": operator, "system": system, "cell": cell} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s JWT is not currently valid", label)
		}
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, system.Subject); err != nil {
		return err
	}
	systemUser, _, err := credentialUser(e.SystemCredentialsFile)
	if err != nil {
		return fmt.Errorf("system account credentials: %w", err)
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return errors.New("controller credentials do not belong to the regional cell account")
	}
	for label, claim := range map[string]*jwt.UserClaims{"system": systemUser, "controller": controller} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s user JWT is not currently valid", label)
		}
	}
	if err := ValidateBrokerControllerCredentials(cfg.CredentialsFile, cfg.Cell, cfg.Instance); err != nil {
		return err
	}
	// The optional membership user is checked at admission, not first at
	// shutdown when it is needed for the metadata step-down.
	if e.MembershipCredentialsFile != "" {
		if err := ValidateMembershipCredentials(e.MembershipCredentialsFile, cfg.Cell, system.Subject); err != nil {
			return err
		}
	}
	for label, files := range map[string]TLSFiles{"client": cfg.TLS, "listener": e.TLS, "route": e.RouteTLS} {
		if err := validateCurrentTLSFiles(files, label); err != nil {
			return fmt.Errorf("%s TLS material: %w", label, err)
		}
	}
	if cfg.Replicas > 1 {
		password, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return fmt.Errorf("NATS route secret: %w", err)
		}
		defer clear(password)
		if len(strings.TrimSpace(string(password))) < 16 {
			return errors.New("NATS route secret is too short")
		}
	}
	return nil
}

func newAccountResolver(system, systemJWT, cell, cellJWT string) *accountResolver {
	return &accountResolver{system: system, cell: cell,
		claims: map[string]string{system: systemJWT, cell: cellJWT}}
}

func (r *accountResolver) Fetch(name string) (string, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	if raw, ok := r.claims[name]; ok {
		return raw, nil
	}
	return "", server.ErrMissingAccount
}

func (r *accountResolver) Store(name, raw string) error {
	if name != r.cell {
		return server.ErrMissingAccount
	}
	claim, err := jwt.DecodeAccountClaims(raw)
	if err != nil || claim.Subject != name {
		return errors.New("replacement broker account JWT is invalid")
	}
	r.mu.Lock()
	if r.linkCell != "" {
		if err := verifyLinkAccount(claim, r.linkCell); err != nil {
			r.mu.Unlock()
			return fmt.Errorf("replacement cell account JWT widens the link contract: %w", err)
		}
	}
	if r.contract != nil {
		system, systemErr := jwt.DecodeAccountClaims(r.claims[r.system])
		interregion, interregionErr := jwt.DecodeAccountClaims(r.claims[r.interregion])
		if systemErr != nil || interregionErr != nil ||
			r.contract.verify(system, claim, interregion, r.links) != nil {
			r.mu.Unlock()
			return errors.New("replacement cell account JWT widens the interregion contract")
		}
	}
	if prior := r.claims[name]; prior != raw {
		old, oldErr := jwt.DecodeAccountClaims(prior)
		if oldErr != nil || claim.IssuedAt <= old.IssuedAt {
			r.mu.Unlock()
			return errors.New("replacement broker account JWT issued-at must strictly increase")
		}
	}
	r.claims[name] = raw
	r.mu.Unlock()
	return nil
}

func (*accountResolver) IsReadOnly() bool { return false }

// IsTrackingUpdate reports true so the server never subscribes to
// $SYS.REQ.ACCOUNT.*.CLAIMS.UPDATE. That handler installs a pushed claim
// without calling Store, so a routed or client-sent operator-signed claim
// would skip the interregion contract check. Every broker instead applies its
// own validated claim from the durable claim store (Runtime.ApplyCellClaim).
func (*accountResolver) IsTrackingUpdate() bool     { return true }
func (*accountResolver) Start(*server.Server) error { return nil }
func (*accountResolver) Reload() error              { return nil }
func (*accountResolver) Close()                     {}

func loadOperatorAccounts(e *Embedded) (*jwt.OperatorClaims, string, string, string, string, error) {
	operatorRaw, err := readSignedJWT(e.OperatorJWTFile)
	if err != nil {
		return nil, "", "", "", "", fmt.Errorf("read regional operator JWT: %w", err)
	}
	operator, err := jwt.DecodeOperatorClaims(operatorRaw)
	if err != nil || !nkeys.IsValidPublicOperatorKey(operator.Subject) ||
		!nkeys.IsValidPublicAccountKey(operator.SystemAccount) {
		return nil, "", "", "", "", errors.New("regional operator JWT is invalid")
	}
	systemRaw, err := readSignedJWT(e.SystemJWTFile)
	if err != nil {
		return nil, "", "", "", "", fmt.Errorf("read regional system JWT: %w", err)
	}
	system, err := jwt.DecodeAccountClaims(systemRaw)
	if err != nil || system.Subject != operator.SystemAccount || !operator.DidSign(system) {
		return nil, "", "", "", "", errors.New("regional system account JWT is invalid")
	}
	cellRaw, err := readSignedJWT(e.CellJWTFile)
	if err != nil {
		return nil, "", "", "", "", fmt.Errorf("read regional cell JWT: %w", err)
	}
	cell, err := jwt.DecodeAccountClaims(cellRaw)
	if err != nil || !nkeys.IsValidPublicAccountKey(cell.Subject) ||
		cell.Subject == system.Subject || !operator.DidSign(cell) {
		return nil, "", "", "", "", errors.New("regional cell account JWT is invalid")
	}
	return operator, systemRaw, cellRaw, system.Subject, cell.Subject, nil
}

func credentialUser(path string) (*jwt.UserClaims, string, error) {
	data, err := readPrivateFile(path, 64<<10)
	if err != nil {
		return nil, "", err
	}
	defer clear(data)
	return credentialUserBytes(data)
}

func credentialUserBytes(data []byte) (*jwt.UserClaims, string, error) {
	raw, err := nkeys.ParseDecoratedJWT(data)
	if err != nil {
		return nil, "", err
	}
	claim, err := jwt.DecodeUserClaims(raw)
	if err != nil {
		return nil, "", err
	}
	pair, err := nkeys.ParseDecoratedUserNKey(data)
	if err != nil {
		return nil, "", err
	}
	defer pair.Wipe()
	public, err := pair.PublicKey()
	if err != nil || public != claim.Subject {
		return nil, "", errors.New("regional credential seed and user JWT differ")
	}
	if claim.BearerToken || claim.ProxyRequired || len(claim.Src) != 0 ||
		len(claim.AllowedConnectionTypes) != 0 && !claim.AllowedConnectionTypes.Contains(jwt.ConnectionTypeInProcess) {
		return nil, "", errors.New("regional JWT depends on client metadata unavailable through the bridge")
	}
	return claim, public, nil
}

func credentialAccount(claim *jwt.UserClaims) string {
	if claim.IssuerAccount != "" {
		return claim.IssuerAccount
	}
	return claim.Issuer
}

func ControllerPublishes(cell string) jwt.StringList {
	publishes := jwt.StringList{protocol.Regional(cell, ">"), protocol.Control(cell, ">"), "$JS.API.>", "$KV.>", "$O.>",
		protocol.Broker(cell, "ticket", ">"), protocol.Broker(cell, "fence", ">")}
	for _, leaf := range protocol.InterRegionObservabilityLeaves() {
		publishes.Add(protocol.AnyRegionObservabilitySubject(leaf))
	}
	publishes.Add(protocol.AnyRegionQuerySubject())
	return publishes
}

// ControllerSubscriptions is the exact regional request surface a controller
// serves, in issuer order. Private inbox and broker grants are added by callers.
func ControllerSubscriptions(cell string) []string {
	return []string{
		protocol.BrokerClaimApplySubject(cell), protocol.AgentObservation(cell, "*", "*"),
		protocol.DeliveryArtifactAdmitSubject(cell), protocol.HostRegisterSubject(cell),
		protocol.PlacementApplySubject(cell), protocol.ManagedUpdatePrepareSubject(cell),
		protocol.BackupOperationSubject(cell), protocol.TerminalSubject(cell, ">"),
		// The seed answers epoch-fenced slot replacement requests from a
		// non-seed authority leader. Material issued before this grant
		// existed lacks it; the request then has no responder and the
		// leader holds the slot, as before.
		protocol.MembershipReplaceSubject(cell),
		// Every controller collects its peers' signed rollout health proofs
		// (controller.rollouts.executor). Material issued before this grant
		// lacks it; such a controller sees no proofs, so its executor holds
		// every rollout in preflight and nothing moves.
		protocol.RolloutProofSubject(cell, ""),
		// Read-only query services this region answers for every region.
		protocol.Regional(cell, "query", ">"),
		// The global home builds the roster from every region's heartbeat.
		// Material issued before this grant lacks it; the home then keeps no
		// roster, and its peers keep their last one.
		protocol.AnyRegionHealthSubject(),
		// Every region's dashboard rollup (TS-805), carried by the link.
		// Material issued before this grant lacks it; such a follower's
		// global view stays empty and the leader holds only its own rollup.
		protocol.RegionRollupGrant,
	}

func ValidateBrokerControllerCredentials(path, cell, broker string) error {
	data, err := readPrivateFile(path, 64<<10)
	if err != nil {
		return fmt.Errorf("broker controller credentials: %w", err)
	}
	defer clear(data)
	return ValidateBrokerControllerCredentialBytes(data, cell, broker)
}

// ValidateBrokerControllerCredentialBytes checks the same contract before a
// root-signed material generation installs controller credentials.
func ValidateBrokerControllerCredentialBytes(data []byte, cell, broker string) error {
	if !cellName.MatchString(cell) || !cellName.MatchString(broker) {
		return errors.New("broker controller credential cell or instance is invalid")
	}
	claim, public, err := credentialUserBytes(data)
	if err != nil {
		return fmt.Errorf("broker controller credentials: %w", err)
	}
	ticket := protocol.Broker(cell, "ticket", ">")
	fencePublish := protocol.Broker(cell, "fence", ">")
	fenceReceive := protocol.Broker(cell, "fence", broker)
	if !slices.Contains(claim.Pub.Allow, ticket) || !slices.Contains(claim.Pub.Allow, fencePublish) ||
		!slices.Contains(claim.Sub.Allow, ticket) || !slices.Contains(claim.Sub.Allow, fenceReceive) {
		return errors.New("broker controller credentials lack ticket or instance-bound fence grants")
	}
	allowedSubscriptions := map[string]bool{
		inboxPrefix(cell, public) + ".>": true,
		ticket:                           true, fenceReceive: true,
	}
	for _, subject := range ControllerSubscriptions(cell) {
		allowedSubscriptions[subject] = true
	}
	for _, subject := range GlobalControllerRequests() {
		allowedSubscriptions[subject] = true
	}
	// Optional read-only member telemetry (observability snapshots). The
	// issuer does not grant it today; it is accepted, not required.
	allowedSubscriptions[protocol.ObservabilityGrant(cell)] = true
	for _, grant := range claim.Sub.Allow {
		if !allowedSubscriptions[grant] {
			return fmt.Errorf("broker controller credentials have unscoped subscription %q", grant)
		}
	}
	if !slices.Contains(claim.Sub.Allow, inboxPrefix(cell, public)+".>") ||
		!slices.Contains(claim.Sub.Allow, protocol.BrokerClaimApplySubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.ManagedUpdatePrepareSubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.BackupOperationSubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.TerminalSubject(cell, ">")) ||
		len(claim.Pub.Deny) != 0 || len(claim.Sub.Deny) != 0 ||
		claim.Resp == nil || claim.Resp.MaxMsgs != 1 ||
		claim.Resp.Expires <= 0 || claim.Resp.Expires > 5*time.Second {
		return errors.New("broker controller credentials need a private inbox and one bounded response grant")
	}
	return nil

func validateSystemCredentials(path, cell, cellAccount, systemAccount string) error {
	data, err := readPrivateFile(path, 64<<10)
	if err != nil {
		return fmt.Errorf("system account credentials: %w", err)
	}
	defer clear(data)
	return ValidateSystemCredentials(data, cell, cellAccount, systemAccount)
}

// ValidateSystemCredentials checks a system account credentials file's bytes:
// a seed that matches its JWT, issued by systemAccount, with only the cell
// claim-update and private reply grants.
func ValidateSystemCredentials(data []byte, cell, cellAccount, systemAccount string) error {
	claim, public, err := credentialUserBytes(data)
	if err != nil {
		return fmt.Errorf("system account credentials: %w", err)
	}
	if credentialAccount(claim) != systemAccount ||
		len(claim.Pub.Allow) != 1 || claim.Pub.Allow[0] != "$SYS.REQ.ACCOUNT."+cellAccount+".CLAIMS.UPDATE" ||
		len(claim.Pub.Deny) != 0 || len(claim.Sub.Allow) != 1 ||
		claim.Sub.Allow[0] != inboxPrefix(cell, public)+".>" || len(claim.Sub.Deny) != 0 ||
		claim.Resp != nil {
		return errors.New("system account credentials must have only the cell claim-update and private reply grants")
	}
	return nil
}

func pinNodeIdentity(dir, cell, instance, nodeID string) error {
	return pinNodeIdentityWithSync(dir, cell, instance, nodeID, syncIdentityDirectory)
}

func pinNodeIdentityWithSync(dir, cell, instance, nodeID string, syncDirectory func(string) error) error {
	if cell == "" || instance == "" || !validNodeID(nodeID) {
		return fmt.Errorf("%w: invalid Raft store identity", ErrStoreIdentity)
	}
	want := nodeIdentity{Version: 1, Cell: cell, Instance: instance, NodeID: nodeID}
	path := filepath.Join(dir, nodeIdentityFile)
	check := func() error {
		info, err := os.Lstat(path)
		if err != nil {
			return err
		}
		if !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 || info.Size() > 1024 {
			return fmt.Errorf("%w: invalid node identity file", ErrStoreIdentity)
		}
		wire, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		var recorded nodeIdentity
		if err := protocol.DecodeStrict(wire, &recorded, 1024); err != nil || recorded != want {
			return fmt.Errorf("%w: node identity differs from this cell/controller and Raft ID", ErrStoreIdentity)
		}
		return nil
	}
	if err := check(); !errors.Is(err, fs.ErrNotExist) {
		if err != nil {
			return err
		}
		return syncDirectory(dir)
	}
	wire, err := json.Marshal(want)
	if err != nil {
		return err
	}
	temp, err := os.CreateTemp(dir, "node-identity.*")
	if err != nil {
		return err
	}
	defer os.Remove(temp.Name())
	defer temp.Close()
	if _, err := temp.Write(wire); err != nil {
		return err
	}
	if err := temp.Sync(); err != nil {
		return err
	}
	if err := temp.Close(); err != nil {
		return err
	}
	// Link publishes a complete record without replacing another starter's pin.
	if err := os.Link(temp.Name(), path); err != nil && !errors.Is(err, fs.ErrExist) {
		return err
	}
	if err := syncDirectory(dir); err != nil {
		return err
	}
	return check()
}

func pinStoreIdentity(dir, name, legacy string) error {
	path := filepath.Join(dir, storeIdentityFile)
	recorded, err := os.ReadFile(path)
	if err == nil {
		if owner := strings.TrimSuffix(string(recorded), "\n"); owner != name {
			return fmt.Errorf("%w: store %s belongs to %q, not %q; the cell must be rebuilt (TS-470)", ErrStoreIdentity, dir, owner, name)
		}
		return nil
	}
	if !errors.Is(err, fs.ErrNotExist) {
		return fmt.Errorf("read NATS store identity: %w", err)
	}
	if name != legacy {
		entries, err := os.ReadDir(filepath.Join(dir, "jetstream"))
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return fmt.Errorf("read NATS store: %w", err)
		}
		if len(entries) > 0 {
			return fmt.Errorf("%w: store %s holds JetStream state of %q, not %q; the cell must be rebuilt (TS-470)", ErrStoreIdentity, dir, legacy, name)
		}
	}
	temp, err := os.CreateTemp(dir, storeIdentityFile+".*")
	if err != nil {
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	defer os.Remove(temp.Name())
	if _, err := temp.WriteString(name + "\n"); err != nil {
		temp.Close()
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	if err := temp.Close(); err != nil {
		return fmt.Errorf("record NATS store identity: %w", err)
	}
	return os.Rename(temp.Name(), path)
}

// drainConnection lets in-flight publishes and acknowledgements finish.
// nats.go drains asynchronously, so an immediate Close would cancel the drain.
func drainConnection(conn *nats.Conn, timeout time.Duration) {
	if conn.IsClosed() {
		return
	}
	if err := conn.Drain(); err == nil {
		deadline := time.Now().Add(timeout)
		for !conn.IsClosed() && time.Now().Before(deadline) {
			time.Sleep(10 * time.Millisecond)
		}
	}
	conn.Close()
}

// stopServer hands off leadership before the embedded server stops. A broker
// that already died skips straight to Shutdown, which is idempotent.
func (r *Runtime) stopServer() {
	if r.server.Running() && r.server.JetStreamIsClustered() {
		r.handOffLeadership(closeHandoffTimeout)
		// Lame-duck mode transfers every remaining Raft leadership, including
		// the metadata leader, and waits for the transfer before stopping
		// JetStream. NATS skips it when the server has no client listener
		// (production DontListen); Shutdown below still steps every Raft
		// leader down first, only without waiting for the transfer.
		r.server.LameDuckShutdown()
	}
	r.server.Shutdown()
	r.server.WaitForShutdown()
}

