// fcAt is a 2026 UTC time at hour o'clock.
func fcAt(month time.Month, d, hour int) time.Time {
	return time.Date(2026, month, d, hour, 0, 0, 0, time.UTC)
}

// fcDays is one day of cents for each day from first to last of month.
func fcDays(month time.Month, first, last int, cents uint64) []Day {
	var days []Day
	for d := first; d <= last; d++ {
		days = append(days, Day{Day: fcAt(month, d, 0), Cents: cents})
	}
	return days
}

func fcReport(observed, through time.Time, days ...Day) Report {
	return Report{Version: Version, Cell: "gru", OCIRegion: "sa-saopaulo-1", Currency: "USD",
		ObservedAt: observed, Through: through, Days: days}
}

// midMonthReport is 16 October at noon with complete days to 13 October.
// Days 1 to 13 cost 1000 each, 14 and 15 are partial at 500 each.
func midMonthReport() Report {
	days := append(fcDays(time.October, 1, 13, 1000),
		Day{Day: fcAt(time.October, 14, 0), Cents: 500},
		Day{Day: fcAt(time.October, 15, 0), Cents: 500})
	return fcReport(fcAt(time.October, 16, 11), fcAt(time.October, 14, 0), days...)
}

func midMonthForecast() Forecast {
	return Forecast{
		Currency:         "USD",
		ObservedAt:       fcAt(time.October, 16, 11),
		Through:          fcAt(time.October, 14, 0),
		MonthToDateCents: 14000,
		CompleteCents:    13000,
		RateFrom:         fcAt(time.October, 7, 0),
		AveragedDays:     7,
		RateCents:        1000,
		DaysLeft:         18,
		MonthEndCents:    31000,
		NextMonthCents:   30000,
	}
}

// Project forecasts the month of now from the report. Hosts add the cost
// the daily rate has not averaged yet, so the forecast errs high, never low.
func Project(report Report, now time.Time, hosts []Host) Forecast {
	monthStart, monthEnd := monthBounds(now)
	nextEnd := monthEnd.AddDate(0, 1, 0)
	through := report.Through
	forecast := Forecast{Currency: report.Currency, ObservedAt: report.ObservedAt, Through: through}

	for _, entry := range report.Days {
		inMonth := !entry.Day.Before(monthStart)
		if inMonth && entry.Day.Before(monthEnd) {
			forecast.MonthToDateCents += entry.Cents
		}
		if inMonth && entry.Day.Before(through) {
			forecast.CompleteCents += entry.Cents
		}
	}

	// A new region averages only the days it has, so its rate is not diluted
	// by days before it existed.
	from := through.Add(-RateDays * day)
	if len(report.Days) > 0 && report.Days[0].Day.After(from) {
		from = report.Days[0].Day
	}
	if from.After(through) {
		from = through
	}
	n := int(through.Sub(from) / day)
	var window uint64
	for _, entry := range report.Days {
		if !entry.Day.Before(from) && entry.Day.Before(through) {
			window += entry.Cents
		}
	}
	forecast.RateFrom = from
	forecast.AveragedDays = n
	if n > 0 {
		forecast.RateCents = ceilDiv(window, uint64(n))
	}

	var pending uint64
	for _, host := range hosts {
		daily := ceilDiv(host.MonthlyCents*12, 365)
		if n == 0 {
			pending += daily
			continue
		}
		var covered int
		switch {
		case !host.Created.IsZero() && !host.Created.After(from):
			covered = n
		case host.Created.IsZero() || !host.Created.Before(through):
			covered = 0
		default:
			covered = min(n, int(through.Sub(host.Created)/day))
		}
		missed := n - covered
		pending += ceilDiv(daily*uint64(missed), uint64(n))
	}
	forecast.PendingDailyCents = pending

	start := through
	if start.Before(monthStart) {
		start = monthStart
	}
	forecast.DaysLeft = int(monthEnd.Sub(start) / day)
	perDay := forecast.RateCents + pending
	forecast.MonthEndCents = forecast.CompleteCents + perDay*uint64(forecast.DaysLeft)
	forecast.NextMonthCents = perDay * uint64(nextEnd.Sub(monthEnd)/day)
	return forecast
}

// ceilDiv rounds up, so every division in a projection errs high.
func ceilDiv(a, b uint64) uint64 {
	return (a + b - 1) / b
}

// monthBounds returns the UTC month holding at and the next month's start.
func monthBounds(at time.Time) (time.Time, time.Time) {
	at = at.UTC()
	start := time.Date(at.Year(), at.Month(), 1, 0, 0, 0, 0, time.UTC)
	return start, start.AddDate(0, 1, 0)
}

